function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function recordActivity(type,text,project=state.project,meta={}){const a=pd(project).activity||(pd(project).activity=[]);a.unshift({id:crypto.randomUUID(),type,text,at:new Date().toISOString(),meta});if(a.length>120)a.length=120;persist();if(project===state.project)renderActivity();}
function leadScore(x){if(Number(x.stage)>=4)return 0;let score=[18,16,24,8,0][Number(x.stage)||0]||0;const v=Number(x.value)||0;score+=v>=100000?25:v>=50000?20:v>=20000?15:v>=5000?9:3;if(x.contact)score+=10;if(x.source)score+=4;if(x.note)score+=4;if(x.followUp){const today=dayKey(),f=x.followUp;if(f<today)score+=25;else if(f===today)score+=18;}const age=(Date.now()-new Date(x.createdAt||Date.now()).getTime())/86400000;if(age>10&&Number(x.stage)<2)score-=8;return Math.max(0,Math.min(100,Math.round(score)));}
function priorityLeads(project=state.project){return pd(project).leads.filter(x=>Number(x.stage)<4).map(x=>({...x,_score:leadScore(x)})).sort((a,b)=>b._score-a._score||((b.value||0)-(a.value||0)));}
