async function api(url,opt={}){let r;try{r=await fetch(url,{credentials:'same-origin',signal:opt.signal||AbortSignal.timeout(70000),...opt,headers:{...(opt.body instanceof Blob?{}:{'content-type':'application/json'}),...(opt.headers||{})}});}catch(e){throw new Error(e.name==='TimeoutError'?'Server neodpověděl včas. Zkus akci znovu.':'Síťové spojení se přerušilo.');}const j=await r.json().catch(()=>({}));if(r.status===401&&String(j.error||'')==='AUTH_REQUIRED'){showAuth();throw new Error(j.error||'AUTH_REQUIRED');}if(!r.ok){const e=new Error(j.error||r.statusText);e.status=r.status;e.code=j.code;e.subcode=j.subcode;throw e;}return j;}
