function executionQueue(project=state.project){
  const p=pd(project), today=dayKey(), rows=[];
  (p.leads||[]).filter(x=>Number(x.stage)<4).forEach(x=>{
    if(!x.followUp) rows.push({kind:'lead',score:86,title:`Nastavit další krok: ${x.name}`,detail:'Lead nemá termín follow-upu.',action:'crm',id:x.id});
    else if(x.followUp<=today) rows.push({kind:'lead',score:x.followUp<today?100:92,title:`Follow-up: ${x.name}`,detail:x.followUp<today?'Po termínu':'Dnes',action:'crm',id:x.id});
  });
  (p.quotes||[]).filter(x=>x.status!=='Uzavřeno').forEach(x=>{
    if(x.followUp&&x.followUp<=today) rows.push({kind:'quote',score:88,title:`Prověřit nabídku: ${x.name||x.customer||'bez názvu'}`,detail:'Nabídka čeká na další obchodní krok.',action:'sales',id:x.id});
  });
  (p.jobs||[]).filter(x=>!['Hotovo','Uzavřeno'].includes(x.status)).forEach(x=>{
    if(x.due&&x.due<today) rows.push({kind:'job',score:90,title:`Zakázka po termínu: ${x.name||x.customer||'bez názvu'}`,detail:'Ověřit stav, termín a vlastníka.',action:'jobs',id:x.id});
  });
  return rows.sort((a,b)=>b.score-a.score).slice(0,12);
}
function renderAutopilot(){
  const e=$('#autopilotQueue'); if(!e)return;
  const rows=executionQueue();
  e.innerHTML=rows.length?rows.map(x=>`<div class=item><div class=priority-row><strong>${esc(x.title)}</strong><span class=score-badge>${x.score}</span></div><div class=muted>${esc(x.detail)}</div><div class=item-actions><button class="btn small autopilotOpen" data-tab="${x.action}">Otevřít</button></div></div>`).join(''):'<div class=item>Žádný kritický úkol. Systém je čistý.</div>';
  $$('.autopilotOpen').forEach(b=>b.onclick=()=>activateTab(b.dataset.tab));
  const summary=$('#autopilotSummary'); if(summary)summary.textContent=`${rows.length} prioritních úkolů · ${rows.filter(x=>x.score>=90).length} kritických`;
}
