function truthGuard(text,project=state.project){const t=String(text||'').toLowerCase(),risks=[];if(project==='jihoceske'){
  const rules=[[/\b(certifikovan|certifikace|autorizovan)[a-zá-ž]*/i,'Certifikace/oprávnění není ověřené.'],[/\b(provádíme|děláme|zajišťujeme)\s+(revize|revizi)\b/i,'Revize musí být formulovaná jako spolupráce s revizním technikem.'],[/\b(vlastní|náš)\s+(revizní technik|elektrikář)\b/i,'Nevydávej externí spolupráci za vlastní oprávnění nebo zaměstnance.'],[/\b(stovky|desítky)\s+realizací\b/i,'Počet realizací není ověřený.'],[/\bgarantujeme\b/i,'Garance je příliš silné tvrzení bez podkladu.']];
  for(const [re,msg] of rules)if(re.test(t))risks.push(msg);
}return risks;}
function assertTruthBeforePublish(text){const risks=truthGuard(text);if(!risks.length)return true;return confirm('KONTROLA TVRZENÍ\n\n'+risks.map(x=>'• '+x).join('\n')+'\n\nText nejdřív zkontroluj. Přesto pokračovat?');}
