  if(!text)return;
  const state=s?.state||'unknown';
  const title=s?.valid?'Meta je připojená':state==='expired'?'Meta token je neplatný / vypršel':s?.configured?'Meta připojení potřebuje opravu':'Meta zatím není nastavená';
