function renderCampaign(){const box=$('#campaignOut'),c=pd().lastCampaign;if(!box)return;if(!c){box.innerHTML='<div class=item>Zatím bez kampaně. Jedno zadání vytvoří post, Stories, carousel i Reel koncept.</div>';return;}const story=(c.stories||[]).map((x,i)=>`<div class=campaign-mini><span>STORY ${i+1}</span><strong>${esc(x.headline||'')}</strong><small>${esc(x.text||'')}</small></div>`).join(''),car=(c.carousel||[]).map((x,i)=>`<div class=campaign-mini><span>${i+1}</span><strong>${esc(x.headline||'')}</strong><small>${esc(x.text||'')}</small></div>`).join('');box.innerHTML=`<div class=campaign-grid><div class=campaign-block><span class=format-badge>POST</span><strong>${esc(c.post?.headline||c.title||'')}</strong><p>${esc(c.post?.caption||'')}</p></div><div class=campaign-block><span class=format-badge>STORIES</span><div class=campaign-mini-grid>${story}</div></div><div class=campaign-block><span class=format-badge>CAROUSEL</span><div class=campaign-mini-grid>${car}</div></div><div class=campaign-block><span class=format-badge>REEL</span><strong>${esc(c.reel?.hook||'')}</strong><p>${esc(c.reel?.concept||'')}</p></div></div><div class=item-actions><button class="btn small campaignPost">Post do editoru</button><button class="btn small campaignReel">Reel do studia</button><button class="btn small campaignExport">Export balíčku</button></div>`;box.querySelector('.campaignPost')?.addEventListener('click',()=>{const p=c.post||{};$('#postText').value=[p.caption,c.cta,(c.hashtags||[]).join(' ')].filter(Boolean).join('\n\n');pd().draft.postText=$('#postText').value;persist();activateTab('content');});box.querySelector('.campaignReel')?.addEventListener('click',()=>{$('#reelGoal').value=c.goal||$('#campaignGoal').value;$('#reelBrief').value=[c.reel?.hook,c.reel?.concept].filter(Boolean).join('\n');pd().draft.reelGoal=$('#reelGoal').value;pd().draft.reelBrief=$('#reelBrief').value;persist();activateTab('reels');});box.querySelector('.campaignExport')?.addEventListener('click',()=>downloadText(`campaign-${dayKey()}.json`,JSON.stringify(c,null,2),'application/json'));}
function renderWorker(){
  const out=$('#workerSummary'),q=$('#workerQueue'),c=pd().lastContentWorker;
  if(!out||!q)return;
  if(!c){out.innerHTML='<div class=item>Pracovník zatím neběžel.</div>';q.innerHTML='<div class=item>Fronta je prázdná.</div>';$('#workerReadyCount').textContent='0';return;}
  const plan=Array.isArray(c.week)?c.week:[],ready=[];
  if(c.campaign?.post?.caption)ready.push({type:'POST',title:c.campaign.post.headline||c.campaign.title||'Post',text:c.campaign.post.caption});
  if(c.campaign?.reel?.concept)ready.push({type:'REEL',title:c.campaign.reel.hook||'Reel koncept',text:c.campaign.reel.concept});
  for(const st of c.campaign?.stories||[])if(st?.text)ready.push({type:'STORY',title:st.headline||'Story',text:st.text});
  const rows=plan.map((x,i)=>`<div class=item><strong>${esc(x.day||`Den ${i+1}`)} · ${esc(x.topic||'Téma')}</strong><span class=muted>${esc(x.goal||'')}</span>${x.photosCount?`<span class=muted>${esc(x.photosCount)} foto</span>`:''}</div>`).join('');
  out.innerHTML=`<div class=item><strong>${esc(c.title||'Content Worker')}</strong><div class=muted>${esc(c.goal||'')}</div><div class=muted>Spuštěno ${esc(new Date(c.createdAt).toLocaleString('cs-CZ'))} · provider ${esc(c.provider||'auto')}</div></div>${rows||'<div class=item>Bez plánu.</div>'}`;
  q.innerHTML=ready.map((x,i)=>`<div class=item><span class=format-badge>${esc(x.type)}</span><strong>${esc(x.title)}</strong><span class=muted>${esc(x.text)}</span><div class=item-actions>${x.type==='POST'?`<button class="btn small workerPost" data-i="${i}">Do editoru</button>`:''}${x.type==='REEL'?`<button class="btn small workerReel" data-i="${i}">Do Reels</button>`:''}</div></div>`).join('')||'<div class=item>Žádný připravený draft.</div>';
  $('#workerReadyCount').textContent=String(ready.length);
  q.querySelectorAll('.workerPost').forEach(b=>b.onclick=()=>{const x=ready[Number(b.dataset.i)];$('#postText').value=x.text;pd().draft.postText=x.text;persist();activateTab('content');toast('Post předán do editoru.','ok');});
  q.querySelectorAll('.workerReel').forEach(b=>b.onclick=()=>{const x=ready[Number(b.dataset.i)];const cc=pd().lastContentWorker?.campaign||{};$('#reelGoal').value=cc.goal||$('#workerGoal').value;$('#reelBrief').value=[x.title,x.text].filter(Boolean).join('\n');pd().draft.reelGoal=$('#reelGoal').value;pd().draft.reelBrief=$('#reelBrief').value;persist();activateTab('reels');toast('Reel koncept předán do Reels Studio.','ok');});
}
async function runContentWorker(){
  const runProject=state.project,goal=$('#workerGoal').value.trim()||'udržovat pravidelný obsah a podporovat aktuální obchodní cíl',offer=$('#workerOffer').value.trim(),audience=$('#workerAudience').value.trim(),days=Number($('#workerDays').value)||7,box=$('#workerStatus');
  captureDraft();$('#workerState').textContent='Pracuje…';$('#workerState').className='pill warn';box.textContent='Pracovník načítá projekční kontext a připravuje plán…';
  try{
    const media=pd(runProject).mediaCatalog.filter(x=>Number(x.quality)>=5).slice(0,120);
    const weekRes=await ai('weekly',`Cíl pracovníka: ${goal}. Nabídka: ${offer||'aktuální služby projektu'}. Publikum: ${audience||'relevantní zákazníci a partneři'}. Navrhni ${days} dní obsahu.`,ctx(runProject,{mediaCatalog:media,worker:{goal,offer,audience,days}}),[],runProject);
    const week=parseJSONish(weekRes.text);if(!Array.isArray(week))throw new Error('Pracovník nevrátil validní plán.');
    pd(runProject).calendar=week.slice(0,7);
    let campaign=null,campaignProvider='';
    if($('#workerAutoPrepare')?.checked){
      const cRes=await ai('campaign',`Cíl: ${goal}. Nabídka/služba: ${offer}. Publikum: ${audience||'relevantní zákazník nebo B2B partner'}. Připrav jednu hlavní mini-kampaň navázanou na nejdůležitější téma z plánu.`,ctx(runProject,{mediaCatalog:media,week:week.slice(0,7),worker:{goal,offer,audience,days}}),[],runProject);
      campaign=parseJSONish(cRes.text);campaignProvider=cRes.provider;if(!campaign?.post||!campaign?.reel)throw new Error('Pracovník nevrátil kompletní kampaň.');
    }
    pd(runProject).lastContentWorker={title:'BC Content Worker',goal,offer,audience,days,week:week.slice(0,7),campaign,createdAt:new Date().toISOString(),provider:[weekRes.provider,campaignProvider].filter(Boolean).join(' + ')||weekRes.provider};
    persist();renderCalendar();renderWorker();recordActivity('content',`Content Worker vytvořil ${Math.min(7,week.length)}denní plán${campaign?' + hlavní kampaň':''}`,runProject);
    if(state.project===runProject){$('#workerState').textContent='Hotovo';$('#workerState').className='pill ok';box.textContent='Pracovník dokončil plán. Publikace zůstává pod potvrzením.';toast('Content Worker je hotový.','ok');}
  }catch(e){if(state.project===runProject){$('#workerState').textContent='Chyba';$('#workerState').className='pill bad';box.textContent='Chyba: '+e.message;}}
}
