const nextFrame=()=>new Promise(r=>requestAnimationFrame(()=>r()));
async function ensureMediaFile(m){if(m.file)return m.file;if(m.handle){m.file=await m.handle.getFile();return m.file;}throw new Error('Fotku se nepodařilo načíst.');}
function clearThumbCache(){mediaThumbEpoch++;for(const url of mediaThumbUrls.values())URL.revokeObjectURL(url);mediaThumbUrls.clear();mediaThumbQueue=[];mediaThumbPending.clear();if(mediaThumbObserver)mediaThumbObserver.disconnect();}
function clearMediaRuntime(keepFiles=false){clearThumbCache();if(!keepFiles)mediaFiles=[];}
function cacheMediaThumb(id,url){if(mediaThumbUrls.has(id)){URL.revokeObjectURL(mediaThumbUrls.get(id));mediaThumbUrls.delete(id);}mediaThumbUrls.set(id,url);while(mediaThumbUrls.size>MEDIA_THUMB_CACHE){const first=mediaThumbUrls.keys().next().value,old=mediaThumbUrls.get(first);mediaThumbUrls.delete(first);URL.revokeObjectURL(old);}}
function applyMediaThumb(img,placeholder,url){if(!img?.isConnected)return;img.onload=()=>{img.classList.add('loaded');placeholder?.remove();};img.src=url;}
function pumpMediaThumbs(){while(mediaThumbActive<2&&mediaThumbQueue.length){const job=mediaThumbQueue.shift();mediaThumbActive++;(async()=>{let url='';try{const cached=mediaThumbUrls.get(job.m.id);if(cached){const pending=mediaThumbPending.get(job.m.id);if(pending?.epoch===job.epoch){for(const w of pending.waiters)applyMediaThumb(w.img,w.placeholder,cached);mediaThumbPending.delete(job.m.id);}return;}const file=await ensureMediaFile(job.m),blob=await resizeBlob(file,420,.66);url=URL.createObjectURL(blob);if(job.epoch!==mediaThumbEpoch){URL.revokeObjectURL(url);url='';return;}cacheMediaThumb(job.m.id,url);const pending=mediaThumbPending.get(job.m.id);if(pending?.epoch===job.epoch){for(const w of pending.waiters)applyMediaThumb(w.img,w.placeholder,url);mediaThumbPending.delete(job.m.id);}}catch{const pending=mediaThumbPending.get(job.m.id);if(pending?.epoch===job.epoch){for(const w of pending.waiters)if(w.placeholder)w.placeholder.textContent='NÁHLED NELZE NAČÍST';mediaThumbPending.delete(job.m.id);}}finally{mediaThumbActive--;pumpMediaThumbs();}})();}}
function queueMediaThumb(m,img,placeholder){const cached=mediaThumbUrls.get(m.id);if(cached){applyMediaThumb(img,placeholder,cached);return;}const pending=mediaThumbPending.get(m.id);if(pending?.epoch===mediaThumbEpoch){pending.waiters.push({img,placeholder});return;}mediaThumbPending.set(m.id,{epoch:mediaThumbEpoch,waiters:[{img,placeholder}]});mediaThumbQueue.push({m,epoch:mediaThumbEpoch});pumpMediaThumbs();}
function ensureMediaObserver(){if(mediaThumbObserver)mediaThumbObserver.disconnect();mediaThumbObserver=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting)continue;const img=e.target,m=img._media;if(m)queueMediaThumb(m,img,img.previousElementSibling);mediaThumbObserver.unobserve(img);}},{rootMargin:'260px 0px'});return mediaThumbObserver;}
function updateMediaStatus(filteredCount=null){const filtered=filteredCount??mediaFiles.filter(m=>!mediaSearch||`${m.name} ${m.path}`.toLowerCase().includes(mediaSearch)).length,n=selectedMedia().length;if($('#mediaStats'))$('#mediaStats').textContent=mediaFiles.length?`${mediaFiles.length} fotek · zobrazeno ${Math.min(filtered,mediaVisibleLimit)}${filtered!==mediaFiles.length?` z ${filtered}`:''}`:'Žádná složka';if($('#mediaSelectionStats'))$('#mediaSelectionStats').textContent=`Vybráno ${n} / 10`;updatePostPhotoCount();}
function useFallbackFiles(list){clearMediaRuntime();mediaVisibleLimit=MEDIA_PAGE;mediaSearch='';if($('#mediaLocalSearch'))$('#mediaLocalSearch').value='';mediaFiles=[...list].filter(f=>/^image\/(jpeg|png|webp)$/i.test(f.type)||/\.(jpe?g|png|webp)$/i.test(f.name)).slice(0,MEDIA_MAX_FILES).map(f=>({id:f.webkitRelativePath||f.name,name:f.name,path:f.webkitRelativePath||f.name,file:f,handle:null,sel:false}));mediaFiles.sort((a,b)=>a.path.localeCompare(b.path,'cs',{numeric:true}));renderMedia();toast(`Připraveno ${mediaFiles.length} fotografií. Náhledy se načítají úsporně.`,'ok');}
async function pickFolder(){if(!window.showDirectoryPicker){$('#mediaFolderFallback')?.click();return;}try{const dir=await window.showDirectoryPicker({mode:'read'});clearMediaRuntime();mediaVisibleLimit=MEDIA_PAGE;mediaSearch='';if($('#mediaLocalSearch'))$('#mediaLocalSearch').value='';mediaFiles=[];let count=0,truncated=false;$('#mediaOut').textContent='Načítám pouze seznam souborů… originály zatím neotevírám.';async function walk(h,prefix=''){for await(const [name,x]of h.entries()){if(count>=MEDIA_MAX_FILES){truncated=true;return true;}if(x.kind==='directory'){if(await walk(x,prefix+name+'/'))return true;}else if(/\.(jpe?g|png|webp)$/i.test(name)){const path=prefix+name;mediaFiles.push({id:path,name,path,handle:x,file:null,sel:false});count++;if(count%120===0){updateMediaStatus(count);await nextFrame();}}}return false;}await walk(dir);mediaFiles.sort((a,b)=>a.path.localeCompare(b.path,'cs',{numeric:true}));$('#mediaOut').textContent=truncated?`Kvůli stabilitě telefonu bylo načteno prvních ${MEDIA_MAX_FILES} fotografií.`:'';renderMedia();toast(`Připraveno ${mediaFiles.length} fotografií. Fotky se dekódují jen podle potřeby.`,'ok');}catch(e){if(e.name!=='AbortError')toast(e.message,'bad');}}
function renderMedia(){const g=$('#mediaGrid');if(!g)return;mediaThumbQueue=[];const observer=ensureMediaObserver(),q=mediaSearch.trim().toLowerCase(),filtered=mediaFiles.filter(m=>!q||`${m.name} ${m.path}`.toLowerCase().includes(q)),visible=filtered.slice(0,mediaVisibleLimit),catalog=new Map(pd().mediaCatalog.map(x=>[x.id,x]));g.innerHTML='';if(!visible.length){g.innerHTML=`<div class="media-empty"><strong>${mediaFiles.length?'Nic neodpovídá filtru.':'Vyber složku s fotografiemi.'}</strong><span>${mediaFiles.length?'Zkus jiný název.':'Aplikace načte jen lehké náhledy a originály otevře až při použití.'}</span></div>`;}else{const frag=document.createDocumentFragment();for(const m of visible){const d=document.createElement('div'),a=catalog.get(m.id);d.className='media'+(m.sel?' sel':'');d.dataset.mediaId=m.id;const placeholder=document.createElement('div');placeholder.className='media-placeholder';placeholder.textContent='NÁHLED';const img=document.createElement('img');img.alt=m.name;img.loading='lazy';img.decoding='async';img.dataset.mediaId=m.id;img._media=m;const meta=document.createElement('div');meta.className='media-meta';const check=document.createElement('span');check.className='media-check';check.textContent='✓';const name=document.createElement('small');name.textContent=m.name;meta.append(check,name);d.append(placeholder,img);if(a?.quality){const quality=document.createElement('span');quality.className='quality';quality.textContent=`${a.quality}/10`;d.appendChild(quality);}d.appendChild(meta);d.onclick=()=>{const selected=selectedMedia().length;if(!m.sel&&selected>=10)return toast('Pro jednu akci lze vybrat maximálně 10 fotografií.','bad');m.sel=!m.sel;d.classList.toggle('sel',m.sel);updateMediaStatus(filtered.length);};frag.appendChild(d);observer.observe(img);}g.appendChild(frag);}const more=$('#mediaLoadMore');if(more)more.classList.toggle('hidden',visible.length>=filtered.length);updateMediaStatus(filtered.length);}
async function resizeBlob(file,max=360,quality=.56){const img=await createImageBitmap(file);try{const scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const x=c.getContext('2d',{alpha:false});x.drawImage(img,0,0,c.width,c.height);const blob=await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('Zmenšení obrázku selhalo.')),'image/jpeg',quality));c.width=1;c.height=1;return blob;}finally{img.close?.();}}
async function thumb(file){let blob=await resizeBlob(file,360,.56);if(blob.size>430000)blob=await resizeBlob(file,300,.48);if(blob.size>480000)throw new Error('AI náhled je stále příliš velký: '+file.name);const buf=new Uint8Array(await blob.arrayBuffer());let s='';for(let i=0;i<buf.length;i+=0x8000)s+=String.fromCharCode(...buf.subarray(i,i+0x8000));return {mime:'image/jpeg',data:btoa(s)};}
async function analyzeSelected(){const runProject=state.project,sel=mediaFiles.filter(x=>x.sel).slice(0,10);if(!sel.length)return toast('Vyber až 10 fotek.','bad');$('#mediaOut').textContent='AI analyzuje…';try{const images=[];let total=0;for(const m of sel){const file=await ensureMediaFile(m),im=await thumb(file);total+=Math.floor(im.data.length*3/4);if(total>2800000)throw new Error('AI náhledy jsou dohromady příliš velké.');images.push(im);await nextFrame();}const j=await ai('visual','',ctx(runProject,{files:sel.map(x=>({id:x.id,name:x.name}))}),images,runProject),d=parseJSONish(j.text),now=Date.now(),catalog=pd(runProject).mediaCatalog;if(d?.photos&&Array.isArray(d.photos)){for(const m of sel){const a=d.photos.find(x=>x.id===m.id)||{},row={id:m.id,name:m.name,analysis:JSON.stringify(a),visible:a.visible||'',shotType:a.shotType||'',quality:Number(a.quality)||0,marketingUse:a.marketingUse||'',claimRisks:a.claimRisks||[],tags:a.tags||[],analyzedAt:now},old=catalog.find(x=>x.id===m.id);old?Object.assign(old,row):catalog.push(row);}pd(runProject).lastAlbumAdvice={coverPhotoId:d.coverPhotoId||'',albumOrder:d.albumOrder||[],summary:d.summary||''};persist();if(state.project===runProject){$('#mediaOut').textContent=`[${j.provider}]\n${d.summary||'Analýza dokončena.'}\nTitulní: ${d.coverPhotoId||'—'}`;renderMedia();}}else if(state.project===runProject)$('#mediaOut').textContent=`[${j.provider}]\n${j.text}`;}catch(e){if(state.project===runProject)$('#mediaOut').textContent='Chyba: '+e.message;}}
async function findMedia(){const q=$('#mediaQuery').value.trim(),runProject=state.project;if(!q)return;$('#mediaOut').textContent='AI vybírá…';try{const catalog=pd(runProject).mediaCatalog.map(x=>({id:x.id,name:x.name,visible:x.visible,shotType:x.shotType,quality:x.quality,marketingUse:x.marketingUse,tags:x.tags})),j=await ai('select',q,ctx(runProject,{catalog,wantedCount:10}),[],runProject),ids=parseJSONish(j.text);if(state.project!==runProject)return;$('#mediaOut').textContent=`[${j.provider}]\n${j.text}`;if(Array.isArray(ids)){mediaFiles.forEach(x=>x.sel=ids.slice(0,10).includes(x.id));renderMedia();}}catch(e){if(state.project===runProject)$('#mediaOut').textContent=e.message;}}
function selectedMedia(){return mediaFiles.filter(x=>x.sel).slice(0,10);}
function updatePostPhotoCount(){const n=selectedMedia().length;$('#postPhotoCount').textContent=n?`Vybráno ${n} foto pro aktivní projekt.`:'Bez fotky – bude publikován pouze text.';}
async function sha256(blob){const ab=await blob.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',ab);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function publishBlob(file){let blob=file;if(file.size>2.8*1024*1024)blob=await resizeBlob(file,1920,.82);if(blob.size>2.8*1024*1024)blob=await resizeBlob(file,1600,.72);if(blob.size>3*1024*1024)throw new Error(`Fotku ${file.name} se nepodařilo bezpečně zmenšit pod limit.`);return blob;}
async function preparePhotos(){const rows=[];for(const m of selectedMedia()){const file=await ensureMediaFile(m),blob=await publishBlob(file);rows.push({name:m.name,mime:blob.type||'image/jpeg',size:blob.size,sha256:await sha256(blob),blob});await nextFrame();}return rows;}
async function uploadMetaPhotos(pre,photos,project){if(!photos.length)return[];const manifest=photos.map(({mime,size,sha256})=>({mime,size,sha256})),encoded=btoa(unescape(encodeURIComponent(JSON.stringify(manifest)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const out=[];for(let i=0;i<photos.length;i++){const r=await fetch('/api/meta-photo',{method:'POST',credentials:'same-origin',headers:{'content-type':photos[i].mime,'x-project':project,'x-photo-index':String(i),'x-photo-manifest':encoded,'x-confirm-token':pre.mediaToken},body:photos[i].blob}),j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||`Upload fotky ${i+1} selhal.`);out.push(j);}return out;}
async function publish(schedule=false){const runProject=state.project,message=$('#postText').value.trim(),when=$('#postWhen').value;if(!message&&!selectedMedia().length)return toast('Chybí text nebo fotografie.','bad');if(schedule&&!when)return toast('Vyber datum a čas.','bad');if(!assertTruthBeforePublish(message))return;try{const status=await loadMetaStatus();if(!status?.configured){ if(status?.state==='expired') throw new Error('META_TOKEN_EXPIRED: Meta přístup vypršel. Fotky a obsah můžeš dál připravovat lokálně; pro publikaci nejdřív obnov Meta přístup.'); throw new Error('Meta není pro tento projekt nastavená. Obsah a fotky můžeš dál připravovat lokálně.'); }const photos=await preparePhotos(),manifest=photos.map(({name,mime,size,sha256})=>({name,mime,size,sha256})),payload={project:runProject,message,when,photos:manifest},pre=await api(`/api/meta?action=${schedule?'preview-schedule':'preview-publish'}&project=${runProject}`,{method:'POST',body:JSON.stringify(payload)});if(state.project!==runProject)throw new Error('Projekt byl během přípravy změněn. Akce byla zrušena.');const pv=pre.preview;if(!confirm(`${schedule?'NAPLÁNOVAT':'PUBLIKOVAT'} NA FACEBOOKU\n\nPROJEKT: ${projects[runProject].name}\nFOTKY: ${photos.length}\n\n${pv.message||'(bez textu)'}${pv.when?'\n\nČAS: '+new Date(pv.when).toLocaleString('cs-CZ'):''}`))return;const media=await uploadMetaPhotos(pre,photos,runProject),j=await api(`/api/meta?action=${schedule?'schedule':'publish'}&project=${runProject}`,{method:'POST',body:JSON.stringify({...payload,when:pv.when||when,confirmationToken:pre.confirmationToken,media})});recordActivity('meta',`${schedule?'Naplánován':'Publikován'} Facebook příspěvek`,runProject,{id:j.id||null});toast(`${schedule?'Naplánováno':'Publikováno'}. ID: ${j.id||'OK'}`,'ok');}catch(e){toast('Publikace: '+e.message,'bad');}}
async function loadCommStatus(){const runProject=state.project;try{const s=await api(`/api/comms?action=status&project=${runProject}`);if(state.project!==runProject)return;$('#commStatus').innerHTML=`<div class=item>E-mail: ${s.email?'✓ připraven':'– nenastaven'}</div><div class=item>WhatsApp: ${s.whatsapp?'✓ připraven':'– nenastaven'}</div><div class=item>RCS: ${s.rcs?'✓ připraven':'– nenastaven'} <span class=muted>${esc(s.rcsRegion||'')}</span></div>`;}catch(e){if(state.project===runProject)$('#commStatus').textContent=e.message;}}
function commPayload(project=state.project){return {project,channel:$('#commChannel').value,to:$('#commTo').value.trim(),subject:$('#commSubject').value.trim(),text:$('#commText').value.trim(),when:$('#commWhen').value};}
function commPreview(p){return `PROJEKT: ${projects[p.project]?.name||p.project}\nKANÁL: ${p.channel.toUpperCase()}\nPŘÍJEMCE: ${p.to}\n${p.channel==='email'?`PŘEDMĚT: ${p.subject}\n`:''}\n${p.text}`;}
async function commAi(){const runProject=state.project,p=commPayload(runProject),original=$('#commText').value;$('#commText').value='AI pracuje…';try{const prompt=original||'Napiš krátkou profesionální zprávu pro zákazníka podle kontextu projektu.';const j=await ai('message',prompt,ctx(runProject,{channel:p.channel}),[],runProject);if(state.project===runProject){$('#commText').value=j.text.trim();pd().draft.commText=$('#commText').value;persist();}}catch(e){if(state.project===runProject)$('#commText').value='Chyba: '+e.message;}}
async function commSend(){const runProject=state.project,p=commPayload(runProject);if(!p.to||!p.text)return toast('Chybí příjemce nebo text.','bad');try{const pre=await api(`/api/comms?action=preview-send&project=${runProject}`,{method:'POST',body:JSON.stringify(p)});if(state.project!==runProject)throw new Error('Projekt byl změněn.');if(!confirm('FINÁLNÍ NÁHLED\n\n'+commPreview(pre.preview)+'\n\nOpravdu odeslat?'))return;const j=await api(`/api/comms?action=send&project=${runProject}`,{method:'POST',body:JSON.stringify({...pre.preview,confirmationToken:pre.confirmationToken})});recordActivity('comms',`Odeslána ${p.channel} zpráva`,runProject,{to:p.to});toast('Odesláno. '+(j.result?.id||'OK'),'ok');loadOutbox();}catch(e){toast('Odeslání: '+e.message,'bad');}}
async function commQueue(){const runProject=state.project,p=commPayload(runProject);if(!p.to||!p.text||!p.when)return toast('Chybí příjemce, text nebo čas.','bad');try{const pre=await api(`/api/comms?action=preview-queue&project=${runProject}`,{method:'POST',body:JSON.stringify(p)});if(state.project!==runProject)throw new Error('Projekt byl změněn.');if(!confirm('NAPLÁNOVANÉ ODESLÁNÍ\n\n'+commPreview(pre.preview)+`\n\nČAS: ${new Date(pre.preview.when).toLocaleString('cs-CZ')}\n\nZařadit do fronty?`))return;await api(`/api/comms?action=queue&project=${runProject}`,{method:'POST',body:JSON.stringify({...pre.preview,confirmationToken:pre.confirmationToken})});recordActivity('comms',`Naplánována ${p.channel} zpráva`,runProject,{to:p.to,when:p.when});toast('Zařazeno do fronty.','ok');loadOutbox();}catch(e){toast('Fronta: '+e.message,'bad');}}
async function loadOutbox(){const runProject=state.project;try{const j=await api(`/api/comms?action=list&project=${runProject}`),items=j.items||[];if(state.project!==runProject)return;$('#outbox').innerHTML=items.length?items.map(x=>`<div class=item><strong>${esc(x.channel.toUpperCase())} · ${esc(x.status)}</strong>${esc(x.to)}<div>${esc(x.subject||'')}</div><div class=muted>${x.when?esc(new Date(x.when).toLocaleString('cs-CZ')):''} ${esc(x.lastError||'')}</div><div class=item-actions>${['queued','retry_wait'].includes(x.status)?`<button class="btn small cancelMsg" data-id="${esc(x.id)}">Zrušit</button>`:''}${['failed','needs_review'].includes(x.status)?`<button class="btn small retryMsg" data-id="${esc(x.id)}">Znovu</button>`:''}</div></div>`).join(''):'<div class=item>Fronta tohoto projektu je prázdná.</div>';$$('.cancelMsg').forEach(b=>b.onclick=()=>cancelMsg(b.dataset.id));$$('.retryMsg').forEach(b=>b.onclick=()=>retryMsg(b.dataset.id));}catch(e){if(state.project===runProject)$('#outbox').textContent=e.message;}}
async function cancelMsg(id){const project=state.project;if(!confirm('Zrušit naplánovanou zprávu tohoto projektu?'))return;try{await api(`/api/comms?action=cancel&project=${project}`,{method:'POST',body:JSON.stringify({id,project})});loadOutbox();}catch(e){toast(e.message,'bad');}}
async function retryMsg(id){const project=state.project;try{const pre=await api(`/api/comms?action=preview-retry&project=${project}`,{method:'POST',body:JSON.stringify({id,project})});if(!confirm('Předchozí síťová chyba mohla zprávu doručit. Opravdu ji zařadit znovu?'))return;await api(`/api/comms?action=retry&project=${project}`,{method:'POST',body:JSON.stringify({id,project,confirmationToken:pre.confirmationToken})});loadOutbox();}catch(e){toast(e.message,'bad');}}
async function loadInbox(){const runProject=state.project,box=$('#inboxList');box.textContent='Načítám…';try{const s=await loadMetaStatus();if(!s?.configured){box.innerHTML='<div class=item>Meta není pro tento projekt nastavena.</div>';return;}const p=await api(`/api/meta?action=posts&project=${runProject}`);let arr=[];for(const post of (p.data||[]).slice(0,8)){try{const c=await api(`/api/meta?action=comments&project=${runProject}&id=${encodeURIComponent(post.id)}`);arr.push(...(c.data||[]).map(x=>({...x,postId:post.id})));}catch{}}if(state.project!==runProject)return;$('#kComments').textContent=arr.length;$('#inboxStats').innerHTML=`<div class=item><strong>${arr.length}</strong> načtených komentářů</div>`;box.innerHTML=arr.length?arr.map((x,i)=>`<div class=item><strong>${esc(x.from?.name||'Komentář')}</strong>${esc(x.message||'')}<div class=muted>${esc(new Date(x.created_time).toLocaleString('cs-CZ'))}</div><div class=item-actions><button class="btn small inboxLead" data-i="${i}">Do CRM</button></div></div>`).join(''):'<div class=item>Žádné komentáře.</div>';$$('.inboxLead').forEach(b=>b.onclick=()=>{const x=arr[Number(b.dataset.i)];pd().leads.unshift({id:crypto.randomUUID(),name:x.from?.name||'Facebook lead',contact:'',note:x.message||'',source:'Facebook komentář',value:0,followUp:'',stage:0,createdAt:new Date().toISOString()});recordActivity('crm',`Komentář z Facebooku převeden do CRM: ${x.from?.name||'Facebook lead'}`);renderCRM();renderKpis();toast('Komentář přidán do CRM.','ok');});}catch(e){if(state.project===runProject)box.textContent=e.message;}}
function renderCRM(){const k=$('#kanban'),q=$('#crmSearch').value.trim().toLowerCase(),filter=$('#crmStageFilter').value;k.innerHTML='';stages.forEach((s,si)=>{const c=document.createElement('div');c.className='col';const leads=pd().leads.filter(x=>Number(x.stage||0)===si).filter(x=>filter==='all'||String(si)===filter).filter(x=>!q||`${x.name} ${x.contact} ${x.note} ${x.source}`.toLowerCase().includes(q));c.innerHTML=`<strong>${esc(s)} · ${leads.length}</strong>`;for(const x of leads){const d=document.createElement('div'),due=x.followUp&&x.followUp<dayKey();d.className='item';d.innerHTML=`<div class=priority-row><strong>${esc(x.name)}</strong><span class=score-badge>${leadScore(x)}</span></div><div>${esc(x.contact||'')}</div><div class=lead-value>${money(x.value)}</div><div class=muted>${esc(x.source||'')} · ${esc(x.note||'')}</div>${x.followUp?`<div class="lead-follow ${due?'due':''}">Follow-up: ${esc(new Date(x.followUp+'T12:00:00').toLocaleDateString('cs-CZ'))}</div>`:''}<div class=item-actions>${si>0?`<button class="btn small leadBack" data-id="${x.id}">←</button>`:''}${si<4?`<button class="btn small leadNext" data-id="${x.id}">→</button>`:''}<button class="btn small leadEdit" data-id="${x.id}">Upravit</button><button class="btn small leadComms" data-id="${x.id}">Napsat</button><button class="btn small leadKit" data-id="${x.id}">Follow-up kit</button><button class="btn small leadTomorrow" data-id="${x.id}">Zítra</button><button class="btn small leadDelete" data-id="${x.id}">Smazat</button></div>`;c.appendChild(d);}k.appendChild(c);});$$('.leadBack').forEach(b=>b.onclick=()=>moveLead(b.dataset.id,-1));$$('.leadNext').forEach(b=>b.onclick=()=>moveLead(b.dataset.id,1));$$('.leadEdit').forEach(b=>b.onclick=()=>startEditLead(b.dataset.id));$$('.leadComms').forEach(b=>b.onclick=()=>leadToComms(b.dataset.id));$$('.leadKit').forEach(b=>b.onclick=()=>leadFollowKit(b.dataset.id));$$('.leadDelete').forEach(b=>b.onclick=()=>deleteLead(b.dataset.id));$$('.leadTomorrow').forEach(b=>b.onclick=()=>setFollowTomorrow(b.dataset.id));renderKpis();}
function moveLead(id,dir){const x=pd().leads.find(y=>y.id===id);if(!x)return;const before=Number(x.stage||0);x.stage=Math.min(4,Math.max(0,before+dir));x.updatedAt=new Date().toISOString();if(x.stage===3&&before!==3)x.wonAt=new Date().toISOString();recordActivity('crm',`${x.name}: přesun do ${stages[x.stage]}`);renderCRM();renderSales();}
function setFollowTomorrow(id){const x=pd().leads.find(y=>y.id===id);if(!x)return;const d=new Date();d.setDate(d.getDate()+1);x.followUp=dayKey(d);recordActivity('crm',`${x.name}: follow-up nastaven na zítra`);renderCRM();renderSales();}
function clearLeadForm(){editingLeadId=null;['leadName','leadContact','leadNote','leadSource','leadValue','leadFollow'].forEach(id=>$('#'+id).value='');$('#addLead').textContent='Přidat';$('#cancelLeadEdit').classList.add('hidden');}
function startEditLead(id){const x=pd().leads.find(y=>y.id===id);if(!x)return;editingLeadId=id;$('#leadName').value=x.name||'';$('#leadContact').value=x.contact||'';$('#leadNote').value=x.note||'';$('#leadSource').value=x.source||'';$('#leadValue').value=x.value||'';$('#leadFollow').value=x.followUp||'';$('#addLead').textContent='Uložit změny';$('#cancelLeadEdit').classList.remove('hidden');$('#leadName').focus();}
function leadToComms(id){const x=pd().leads.find(y=>y.id===id);if(!x)return;const contact=(x.contact||'').trim();if(!contact){toast('Lead nemá kontakt. Nejdřív ho doplň.','bad');startEditLead(id);return;}const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact);$('#commChannel').value=email?'email':'whatsapp';$('#commTo').value=contact;$('#commSubject').value=email?`Navázání – ${x.name}`:'';$('#commText').value=`Dobrý den${x.name?', '+x.name:''},\n\nnavazuji na naši předchozí komunikaci. `;pd().draft.commChannel=$('#commChannel').value;pd().draft.commTo=contact;pd().draft.commSubject=$('#commSubject').value;pd().draft.commText=$('#commText').value;persist();recordActivity('crm',`${x.name}: otevřena komunikace`);activateTab('comms');$('#commText').focus();}
async function leadFollowKit(id){const x=pd().leads.find(y=>y.id===id);if(!x)return;const out=$('#crmOut');out.textContent=`AI připravuje follow-up pro ${x.name}…`;try{const j=await ai('leadkit','Připrav obchodní follow-up kit.',ctx(state.project,{lead:{name:x.name,note:x.note,source:x.source,stage:x.stage,value:x.value,followUp:x.followUp}}),[],state.project),d=parseJSONish(j.text);if(!d)throw new Error('AI nevrátila follow-up kit.');x.lastKit={...d,createdAt:new Date().toISOString()};persist();out.textContent=[`PRIORITA: ${d.priority||'—'}`,`DŮVOD SHODY: ${d.fitReason||'—'}`,'',`PRVNÍ / DALŠÍ ZPRÁVA:\n${d.firstMessage||'—'}`,'',`WHATSAPP:\n${d.whatsapp||'—'}`,'',`D+2: ${d.followUps?.d2||'—'}`,`D+5: ${d.followUps?.d5||'—'}`,`D+10: ${d.followUps?.d10||'—'}`,'',`KVALIFIKAČNÍ OTÁZKY:\n${(d.questions||[]).map(q=>'• '+q).join('\n')}`,'',`NÁMITKY:\n${(d.objections||[]).map(o=>'• '+(o.objection||o)+' → '+(o.answer||'')).join('\n')}`,'',`DALŠÍ KROK: ${d.nextStep||'—'}`].join('\n');recordActivity('crm',`${x.name}: vytvořen follow-up kit`);}catch(e){out.textContent='Chyba: '+e.message;}}
function deleteLead(id){if(!confirm('Smazat lead?'))return;const x=pd().leads.find(y=>y.id===id);pd().leads=pd().leads.filter(x=>x.id!==id);if(editingLeadId===id)clearLeadForm();recordActivity('crm',`Smazán lead: ${x?.name||'neznámý'}`);renderCRM();}
function addLead(){const name=$('#leadName').value.trim();if(!name)return toast('Chybí jméno nebo firma.','bad');const data={name,contact:$('#leadContact').value.trim(),note:$('#leadNote').value.trim(),source:$('#leadSource').value.trim(),value:Number(String($('#leadValue').value).replace(/\s/g,'').replace(',','.'))||0,followUp:$('#leadFollow').value};if(editingLeadId){const x=pd().leads.find(y=>y.id===editingLeadId);if(!x)return clearLeadForm();Object.assign(x,data,{updatedAt:new Date().toISOString()});recordActivity('crm',`Upraven lead: ${name}`);}else{pd().leads.unshift({id:crypto.randomUUID(),...data,stage:0,createdAt:new Date().toISOString()});recordActivity('crm',`Nový lead: ${name}`);}clearLeadForm();renderCRM();renderSales();}
async function loadAnalytics(){const runProject=state.project,list=$('#analyticsList');list.textContent='Načítám…';try{const s=await loadMetaStatus();if(!s?.configured){list.innerHTML='<div class=item>Meta není pro tento projekt nastavena.</div>';$('#ads').innerHTML='<div class=item>Bez dat.</div>';return;}const p=await api(`/api/meta?action=posts&project=${runProject}`),rows=(p.data||[]).map(x=>({id:x.id,msg:(x.message||'').slice(0,180),date:x.created_time,reactions:x.reactions?.summary?.total_count||0,comments:x.comments?.summary?.total_count||0,url:x.permalink_url}));if(state.project!==runProject)return;$('#kPosts').textContent=rows.length;list.innerHTML=rows.length?rows.map(x=>`<div class=item><strong>${esc(x.reactions)} reakcí · ${esc(x.comments)} komentářů</strong>${esc(x.msg||'(bez textu)')}<div class=muted>${esc(new Date(x.date).toLocaleString('cs-CZ'))}</div></div>`).join(''):'<div class=item>Bez příspěvků.</div>';if(rows.length){const sorted=[...rows].sort((a,b)=>(b.reactions+b.comments)-(a.reactions+a.comments));pd().learning=[`Nejlepší z posledních příspěvků: ${(sorted[0].msg||'bez textu').slice(0,90)}…`,`Nejvyšší součet reakcí a komentářů: ${sorted[0].reactions+sorted[0].comments}`];persist();renderLearning();}try{const a=await api(`/api/meta?action=ads&project=${runProject}`);if(state.project===runProject)$('#ads').innerHTML=(a.data||[]).map(x=>`<div class=item><strong>${esc(x.campaign_name||'Kampaň')}</strong>Dosah ${esc(x.reach||0)} · kliky ${esc(x.clicks||0)} · útrata ${esc(x.spend||0)}</div>`).join('')||'<div class=item>Bez dat.</div>';}catch(e){if(state.project===runProject)$('#ads').textContent=e.message;}}catch(e){if(state.project===runProject)list.textContent=e.message;}}

const STAGE_WEIGHTS=[.15,.35,.65,1,0];
