  service_local:{label:'Lokální služba',tasks:['Potvrdit rozsah služby a stav před prací','Ověřit přístup, vybavení a podmínky na místě','Fotodokumentace před','Provést dohodnutou službu','Kontrola výsledku','Fotodokumentace po','Předání zákazníkovi a potvrzení otevřených bodů']},
