const monthKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
const numericValue=v=>Number(String(v??'').replace(/\s/g,'').replace(',','.'))||0;
function populateLeadSelect(id,filter=()=>true,placeholder='Vyber lead'){const e=$('#'+id);if(!e)return;const prev=e.value,rows=pd().leads.filter(filter);e.innerHTML=`<option value="">${esc(placeholder)}</option>`+rows.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(stages[Number(x.stage)||0])} · ${esc(money(x.value))}</option>`).join('');if(rows.some(x=>x.id===prev))e.value=prev;}
function pipelineStats(){const p=pd(),active=p.leads.filter(x=>Number(x.stage)<4),weighted=active.reduce((a,x)=>a+(Number(x.value)||0)*(STAGE_WEIGHTS[Number(x.stage)||0]||0),0),m=monthKey(),won=p.leads.filter(x=>Number(x.stage)===3&&monthKey(new Date(x.wonAt||x.updatedAt||x.createdAt||Date.now()))===m).reduce((a,x)=>a+(Number(x.value)||0),0),target=Number(p.targetMonthly)||0;return {active,weighted,won,target,gap:Math.max(0,target-won)};}
function renderSales(){const root=$('#sales');if(!root)return;const st=pipelineStats();$('#salesWeighted').textContent=money(st.weighted);$('#salesWon').textContent=money(st.won);$('#salesTarget').textContent=money(st.target);$('#salesGap').textContent=money(st.gap);if($('#monthlyTarget')&&document.activeElement!==$('#monthlyTarget'))$('#monthlyTarget').value=st.target||'';populateLeadSelect('dealCoachLead',x=>Number(x.stage)<4,'Vyber aktivní lead');populateLeadSelect('quoteLead',x=>Number(x.stage)<4,'Vyber lead pro nabídku');const q=$('#salesQueue'),today=dayKey(),rows=priorityLeads().filter(x=>!x.followUp||x.followUp<=today).slice(0,12);q.innerHTML=rows.length?rows.map(x=>`<div class="item"><div class="priority-row"><strong>${esc(x.name)}</strong><span class="score-badge">${x._score}</span></div><div>${money(x.value)} · ${esc(stages[Number(x.stage)||0])}</div><div class="muted">${x.followUp?(x.followUp<today?'PO TERMÍNU':'DNES'):'CHYBÍ FOLLOW-UP'}${x.source?' · '+esc(x.source):''}</div><div class="item-actions"><button class="btn small salesOpen" data-id="${x.id}">Deal coach</button><button class="btn small salesWrite" data-id="${x.id}">Napsat</button><button class="btn small salesTomorrow" data-id="${x.id}">Zítra</button></div></div>`).join(''):'<div class="item">Dnes není žádný follow-up po termínu ani bez termínu.</div>';q.querySelectorAll('.salesOpen').forEach(b=>b.onclick=()=>{$('#dealCoachLead').value=b.dataset.id;dealCoachRun();});q.querySelectorAll('.salesWrite').forEach(b=>b.onclick=()=>leadToComms(b.dataset.id));q.querySelectorAll('.salesTomorrow').forEach(b=>b.onclick=()=>setFollowTomorrow(b.dataset.id));const id=$('#dealCoachLead')?.value,x=pd().leads.find(y=>y.id===id);if($('#dealCoachScore')){$('#dealCoachScore').textContent=x?`Priorita ${leadScore(x)}`:'Lead —';$('#dealCoachScore').className='pill '+(x&&leadScore(x)>=70?'ok':x?'warn':'subtle');}renderQuotes();}
