async function salesBatchFollow(){const runProject=state.project,today=dayKey(),rows=priorityLeads().filter(x=>!x.followUp||x.followUp<=today).slice(0,8),out=$('#dealCoachOut');if(!rows.length)return toast('Dnes není co řešit.','ok');out.textContent='AI připravuje dávku follow-upů…';try{const safe=rows.map(x=>({name:x.name,stage:x.stage,value:x.value,source:x.source,note:x.note,followUp:x.followUp,score:x._score})),j=await ai('crm','Připrav dnešní dávku follow-upů. Pro každý lead uveď prioritu, cíl kontaktu a jednu krátkou zprávu. Bez kontaktních údajů.',ctx(runProject,{dueLeads:safe}),[],runProject);if(state.project===runProject){out.textContent=`[${j.provider}]\n${j.text}`;recordActivity('sales','AI připravila dávku follow-upů',runProject);}}catch(e){out.textContent='Chyba: '+e.message;}}
async function dealCoachRun(){const id=$('#dealCoachLead').value,x=pd().leads.find(y=>y.id===id),out=$('#dealCoachOut');if(!x)return toast('Vyber lead.','bad');out.textContent=`AI analyzuje ${x.name}…`;try{const runProject=state.project,j=await ai('salescoach','Navrhni nejkratší cestu k dalšímu konkrétnímu obchodnímu kroku.',ctx(runProject,{lead:{name:x.name,note:x.note,source:x.source,stage:x.stage,value:x.value,followUp:x.followUp,score:leadScore(x)}}),[],runProject),d=parseJSONish(j.text);x.lastCoach=d||{text:j.text,createdAt:new Date().toISOString()};pd().lastSalesCoach={leadId:x.id,result:x.lastCoach,createdAt:new Date().toISOString()};persist();out.textContent=d?[`PRIORITA: ${d.priority||'—'}`,`CÍL: ${d.goal||'—'}`,`DALŠÍ KROK: ${d.nextStep||'—'}`,`CO OVĚŘIT: ${(d.verify||[]).join(' · ')||'—'}`,`RIZIKO: ${(d.risks||[]).join(' · ')||'—'}`,`ZPRÁVA: ${d.message||'—'}`].join('\n'):`[${j.provider}]\n${j.text}`;recordActivity('sales',`${x.name}: Deal Coach`,runProject);renderSales();}catch(e){out.textContent='Chyba: '+e.message;}}
function selectedDeal(){return pd().leads.find(x=>x.id===$('#dealCoachLead')?.value);}
