function dealCoachQuote(){const x=selectedDeal();if(!x)return toast('Vyber lead.','bad');$('#quoteLead').value=x.id;$('#quoteTitle').value=`Nabídka – ${x.name}`;$('#quoteScope').value=x.note||'';$('#quoteAmount').value=x.value||'';$('#quoteNote').value='Chybí / ověřit: přesný rozsah, termín, doprava, materiál a odpovědnosti stran.';toast('Lead načten do nabídky. Cena je pouze převzatá z hodnoty leadu – zkontroluj ji.','warn');}
async function quoteAiScope(){const id=$('#quoteLead').value,x=pd().leads.find(y=>y.id===id),out=$('#quoteScope');if(!x)return toast('Vyber lead.','bad');out.value='AI připravuje rozsah…';try{const runProject=state.project,j=await ai('quote','Navrhni pouze rozsah prací a seznam chybí/ověřit. Nevymýšlej cenu, certifikaci, materiál ani termín.',ctx(runProject,{lead:{name:x.name,note:x.note,source:x.source,stage:x.stage}}),[],runProject),d=parseJSONish(j.text);out.value=d?[...(d.scope||[]).map(x=>'• '+x),'',...(d.verify||[]).map(x=>'OVĚŘIT: '+x)].join('\n'):j.text;scheduleDraftSave();}catch(e){out.value='Chyba: '+e.message;}}
function quotePayload(){const id=$('#quoteLead').value,x=pd().leads.find(y=>y.id===id),amountRaw=$('#quoteAmount').value.trim();return {leadId:id||null,leadName:x?.name||'',title:$('#quoteTitle').value.trim()||`Nabídka${x?.name?' – '+x.name:''}`,scope:$('#quoteScope').value.trim(),amount:amountRaw?numericValue(amountRaw):null,validDays:Math.max(1,Math.min(90,Number($('#quoteValidDays').value)||14)),note:$('#quoteNote').value.trim(),status:'draft'};}
function quoteAsText(q){const lines=[`NABÍDKA`,q.title,`Lead: ${q.leadName||'—'}`,`Datum: ${new Date(q.createdAt||Date.now()).toLocaleDateString('cs-CZ')}`,`Platnost: ${q.validDays||14} dní`,`Cena: ${q.amount==null?'chybí / ověřit':money(q.amount)}`,'',`ROZSAH`,q.scope||'chybí / ověřit','',`POZNÁMKY / PODMÍNKY`,q.note||'chybí / ověřit'];if(state.project==='jihoceske')lines.push('','Pozn.: Elektro zapojení a revize jsou případně řešeny ve spolupráci s elektrikářem a revizním technikem, nikoli jako vlastní oprávnění montážního týmu.');return lines.join('\n');}
function quoteSave(){const q=quotePayload();if(!q.leadId&&!q.title)return toast('Vyber lead nebo zadej název.','bad');if(!q.scope)return toast('Doplň rozsah nabídky.','bad');q.id=crypto.randomUUID();q.createdAt=new Date().toISOString();pd().quotes.unshift(q);persist();recordActivity('sales',`Uložena nabídka: ${q.title}`);renderQuotes();toast(q.amount==null?'Nabídka uložena bez ceny – před odesláním cenu ověř.':'Nabídka uložena.','ok');}
function quoteExportCurrent(){const q={...quotePayload(),createdAt:new Date().toISOString()};downloadText(`nabidka-${(q.leadName||'zakazka').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${dayKey()}.txt`,quoteAsText(q));}
function renderQuotes(){const e=$('#quoteList');if(!e)return;e.innerHTML=(pd().quotes||[]).length?pd().quotes.slice(0,20).map(q=>`<div class="quote-card"><div><strong>${esc(q.title)}</strong><span>${esc(q.leadName||'bez leadu')} · ${q.amount==null?'cena ověřit':esc(money(q.amount))}</span></div><div class="item-actions"><button class="btn small quoteExport" data-id="${q.id}">Export</button><button class="btn small quoteToJob" data-id="${q.id}">→ Zakázka</button><button class="btn small quoteDelete" data-id="${q.id}">Smazat</button></div></div>`).join(''):'<div class="item">Zatím bez uložených nabídek.</div>';e.querySelectorAll('.quoteExport').forEach(b=>b.onclick=()=>{const q=pd().quotes.find(x=>x.id===b.dataset.id);if(q)downloadText(`nabidka-${dayKey()}.txt`,quoteAsText(q));});e.querySelectorAll('.quoteDelete').forEach(b=>b.onclick=()=>{if(!confirm('Smazat nabídku?'))return;pd().quotes=pd().quotes.filter(x=>x.id!==b.dataset.id);persist();renderQuotes();});e.querySelectorAll('.quoteToJob').forEach(b=>b.onclick=()=>{const q=pd().quotes.find(x=>x.id===b.dataset.id);if(!q)return;activateTab('jobs');if(q.leadId)$('#jobLead').value=q.leadId;$('#jobName').value=q.title.replace(/^Nabídka\s*[–-]?\s*/i,'')||q.leadName;$('#jobRevenue').value=q.amount??'';$('#jobNote').value=[q.scope,q.note].filter(Boolean).join('\n\n');});}
function csvEscape(v){const x=String(v??'');return /[",\n\r;]/.test(x)?`"${x.replace(/"/g,'""')}"`:x;}
function exportLeadsCsv(){const rows=[['name','contact','value','source','followUp','note','stage'],...pd().leads.map(x=>[x.name,x.contact,x.value,x.source,x.followUp,x.note,x.stage])];downloadText(`crm-leady-${state.project}-${dayKey()}.csv`,rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv;charset=utf-8');}
function parseCsv(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(q){if(c==='"'&&n==='"'){cell+='"';i++;}else if(c==='"')q=false;else cell+=c;}else if(c==='"')q=true;else if(c===','){row.push(cell);cell='';}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell.replace(/\r$/,''));if(row.some(x=>x!==''))rows.push(row);return rows;}
async function importLeadsCsv(file){try{const rows=parseCsv(await file.text());if(rows.length<2)throw new Error('CSV neobsahuje data.');const h=rows[0].map(x=>x.trim()),ix=n=>h.indexOf(n),added=[];for(const r of rows.slice(1)){const name=r[ix('name')]?.trim();if(!name)continue;added.push({id:crypto.randomUUID(),name,contact:r[ix('contact')]?.trim()||'',value:numericValue(r[ix('value')]),source:r[ix('source')]?.trim()||'',followUp:r[ix('followUp')]?.trim()||'',note:r[ix('note')]?.trim()||'',stage:Math.max(0,Math.min(4,Number(r[ix('stage')])||0)),createdAt:new Date().toISOString()});}if(!added.length)throw new Error('Nebyl nalezen žádný platný řádek se jménem.');pd().leads.unshift(...added);persist();renderCRM();renderSales();recordActivity('crm',`Importováno ${added.length} leadů z CSV`);toast(`Importováno ${added.length} leadů.`,'ok');}catch(e){toast('CSV import: '+e.message,'bad');}}
function jobTemplateTasks(key){return (JOB_TEMPLATES[key]||JOB_TEMPLATES.custom).tasks.map(text=>({id:crypto.randomUUID(),text,done:false}));}
function jobStats(){const rows=pd().jobs||[],active=rows.filter(x=>['planned','in_progress','waiting'].includes(x.status)),done=rows.filter(x=>x.status==='done'),today=dayKey(),d30=new Date();d30.setDate(d30.getDate()+30);const limit=dayKey(d30),unpaid=rows.filter(x=>x.paymentStatus!=='paid'&&x.paymentDue),cash30=unpaid.filter(x=>x.paymentDue>=today&&x.paymentDue<=limit).reduce((a,x)=>a+(Number(x.revenue)||0),0),overdue=unpaid.filter(x=>x.paymentDue<today).reduce((a,x)=>a+(Number(x.revenue)||0),0);return {rows,active,done,cash30,overdue};}
function populateJobLeadSelect(){populateLeadSelect('jobLead',x=>Number(x.stage)===3,'Vyber lead ve fázi Zakázka');}
function renderJobs(){const root=$('#jobs');if(!root)return;populateJobLeadSelect();const st=jobStats();$('#jobsActive').textContent=st.active.length;$('#jobsDone').textContent=st.done.length;$('#jobsCash30').textContent=money(st.cash30);$('#jobsOverdueCash').textContent=money(st.overdue);const filter=$('#jobStatusFilter')?.value||'all',board=$('#jobBoard'),labels={planned:'Plán',in_progress:'Probíhá',waiting:'Čeká',done:'Hotovo'};const rows=st.rows.filter(x=>filter==='all'||x.status===filter);board.innerHTML=rows.length?rows.map(j=>{const tasks=j.tasks||[],done=tasks.filter(t=>t.done).length,pct=tasks.length?Math.round(done/tasks.length*100):0;return `<article class="job-card ${esc(j.status)}"><div class="job-head"><div><span class="format-badge">${esc(labels[j.status]||j.status)}</span><strong>${esc(j.name)}</strong><small>${esc(j.location||'místo ověřit')} ${j.date?'· '+esc(new Date(j.date+'T12:00:00').toLocaleDateString('cs-CZ')):''}</small></div><span class="pill subtle">${pct}%</span></div><progress class="job-progress" value="${pct}" max="100">${pct}%</progress><div class="job-meta"><span>${j.revenue?money(j.revenue):'tržba ověřit'}</span><span>${j.paymentDue?'splatnost '+esc(new Date(j.paymentDue+'T12:00:00').toLocaleDateString('cs-CZ')):'splatnost ověřit'}</span></div><div class="job-tasks">${tasks.map(t=>`<label class="job-task"><input type="checkbox" class="jobTaskToggle" data-job="${j.id}" data-task="${t.id}" ${t.done?'checked':''}><span>${esc(t.text)}</span></label>`).join('')}</div><div class="item-actions"><button class="btn small jobCycle" data-id="${j.id}">${j.status==='planned'?'Spustit':j.status==='in_progress'?'Čeká':j.status==='waiting'?'Pokračovat':'Hotovo'}</button><button class="btn small jobPaid" data-id="${j.id}">${j.paymentStatus==='paid'?'Zaplaceno ✓':'Označit zaplaceno'}</button><button class="btn small jobExport" data-id="${j.id}">Export</button><button class="btn small jobDelete" data-id="${j.id}">Smazat</button></div>${j.note?`<div class="muted job-note">${esc(j.note)}</div>`:''}</article>`;}).join(''):'<div class="media-empty"><strong>Zatím bez zakázek.</strong><span>Vyhraný lead můžeš převést na zakázku nebo ji založit ručně.</span></div>';board.querySelectorAll('.jobTaskToggle').forEach(x=>x.onchange=()=>toggleJobTask(x.dataset.job,x.dataset.task,x.checked));board.querySelectorAll('.jobCycle').forEach(b=>b.onclick=()=>cycleJobStatus(b.dataset.id));board.querySelectorAll('.jobPaid').forEach(b=>b.onclick=()=>toggleJobPaid(b.dataset.id));board.querySelectorAll('.jobExport').forEach(b=>b.onclick=()=>exportJob(b.dataset.id));board.querySelectorAll('.jobDelete').forEach(b=>b.onclick=()=>deleteJob(b.dataset.id));renderCashWatch();}
function jobFromLead(){const id=$('#jobLead').value,x=pd().leads.find(y=>y.id===id);if(!x)return toast('Vyber lead ve fázi Zakázka.','bad');$('#jobName').value=x.name;$('#jobRevenue').value=x.value||'';$('#jobNote').value=x.note||'';}
function createJob(){const leadId=$('#jobLead').value,x=pd().leads.find(y=>y.id===leadId),name=$('#jobName').value.trim()||x?.name||'';if(!name)return toast('Chybí název zakázky.','bad');const template=$('#jobTemplate').value||'custom',j={id:crypto.randomUUID(),leadId:leadId||null,name,type:template,location:$('#jobLocation').value.trim(),date:$('#jobDate').value,revenue:numericValue($('#jobRevenue').value),paymentDue:$('#jobPaymentDue').value,paymentStatus:'unpaid',note:$('#jobNote').value.trim(),status:'planned',tasks:jobTemplateTasks(template),createdAt:new Date().toISOString()};pd().jobs.unshift(j);persist();recordActivity('jobs',`Založena zakázka: ${name}`);for(const id of ['jobName','jobLocation','jobDate','jobRevenue','jobPaymentDue','jobNote'])$('#'+id).value='';renderJobs();toast('Zakázka a checklist vytvořeny.','ok');}
function toggleJobTask(jobId,taskId,done){const j=pd().jobs.find(x=>x.id===jobId),t=j?.tasks?.find(x=>x.id===taskId);if(!t)return;t.done=!!done;j.updatedAt=new Date().toISOString();persist();renderJobs();}
function cycleJobStatus(id){const j=pd().jobs.find(x=>x.id===id);if(!j)return;const next={planned:'in_progress',in_progress:'waiting',waiting:'in_progress',done:'done'};if(j.status==='in_progress'&&(j.tasks||[]).length&&(j.tasks||[]).every(t=>t.done))j.status='done';else j.status=next[j.status]||'planned';if(j.status==='done')j.completedAt=new Date().toISOString();recordActivity('jobs',`${j.name}: stav ${j.status}`);renderJobs();}
