function exportJob(id){const j=pd().jobs.find(x=>x.id===id);if(!j)return;downloadText(`zakazka-${j.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${dayKey()}.json`,JSON.stringify(j,null,2),'application/json');}
function deleteJob(id){const j=pd().jobs.find(x=>x.id===id);if(!j||!confirm(`Smazat zakázku ${j.name}?`))return;pd().jobs=pd().jobs.filter(x=>x.id!==id);persist();recordActivity('jobs',`Smazána zakázka: ${j.name}`);renderJobs();}
function renderCashWatch(){const e=$('#cashWatch');if(!e)return;const today=dayKey(),rows=(pd().jobs||[]).filter(x=>x.paymentStatus!=='paid'&&x.paymentDue).sort((a,b)=>a.paymentDue.localeCompare(b.paymentDue)).slice(0,12);e.innerHTML=rows.length?rows.map(j=>`<div class="item"><strong>${esc(j.name)} · ${money(j.revenue)}</strong><div class="muted ${j.paymentDue<today?'cash-overdue':''}">${j.paymentDue<today?'PO SPLATNOSTI':'Splatnost'}: ${esc(new Date(j.paymentDue+'T12:00:00').toLocaleDateString('cs-CZ'))}</div><div class="item-actions"><button class="btn small cashPaid" data-id="${j.id}">Zaplaceno</button></div></div>`).join(''):'<div class="item">Žádné zadané neuhrazené splatnosti.</div>';e.querySelectorAll('.cashPaid').forEach(b=>b.onclick=()=>toggleJobPaid(b.dataset.id));}
function cleanupReelPreview(){clearInterval(reelPreviewTimer);reelPreviewTimer=null;for(const u of reelPreviewUrls)URL.revokeObjectURL(u);reelPreviewUrls=[];window.__bcReelFrames=[];reelPreviewIndex=0;}
async function buildReelPreview(){const plan=pd().lastReelPlan,sel=selectedMedia().slice(0,10),stateEl=$('#reelPreviewState');if(!plan?.shotList?.length)return toast('Nejdřív vytvoř Reel plán.','bad');cleanupReelPreview();stateEl.textContent='Sestavuji lehký 9:16 náhled…';const frames=[];try{for(let i=0;i<plan.shotList.length;i++){const shot=plan.shotList[i],m=sel.length?sel[i%sel.length]:null;let url='';if(m){const file=await ensureMediaFile(m),blob=await resizeBlob(file,720,.68);url=URL.createObjectURL(blob);reelPreviewUrls.push(url);}frames.push({shot,mediaName:m?.name||'',url});await nextFrame();}window.__bcReelFrames=frames;reelPreviewIndex=0;showReelFrame();stateEl.textContent=`Náhled hotový · ${frames.length} scén · ${sel.length} lokálních fotek.`;renderReelTimeline();}catch(e){cleanupReelPreview();stateEl.textContent='Náhled: '+e.message;}}
function renderReelComposer(){const e=$('#reelPreviewState');if(!e)return;const plan=pd().lastReelPlan;if(!plan?.shotList?.length){cleanupReelPreview();$('#reelPhoneMedia').innerHTML='<div class="reel-phone-empty">Vyber fotky a vytvoř Reel plán.</div>';$('#reelPhoneText').textContent='';$('#reelTimeline').innerHTML='<div class="item">Po sestavení uvidíš scénu po scéně.</div>';e.textContent='Náhled je lokální a nic nepublikuje.';}else if(!window.__bcReelFrames?.length){e.textContent=`Plán má ${plan.shotList.length} scén. Klikni Sestavit náhled.`;renderReelTimeline();}}
function showReelFrame(){const frames=window.__bcReelFrames||[],f=frames[reelPreviewIndex],media=$('#reelPhoneMedia'),text=$('#reelPhoneText');if(!f){media.innerHTML='<div class="reel-phone-empty">Bez náhledu</div>';text.textContent='';return;}media.innerHTML=f.url?`<img src="${f.url}" alt="${esc(f.mediaName||'Reel frame')}">`:`<div class="reel-phone-empty">Záběr chybí / dotočit</div>`;text.textContent=f.shot.onScreenText||f.shot.voiceover||'';$$('.timeline-step').forEach((x,i)=>x.classList.toggle('active',i===reelPreviewIndex));}
function renderReelTimeline(){const e=$('#reelTimeline'),frames=window.__bcReelFrames||[],shots=frames.length?frames.map(x=>x.shot):(pd().lastReelPlan?.shotList||[]);e.innerHTML=shots.length?shots.map((x,i)=>`<button class="timeline-step ${i===reelPreviewIndex?'active':''}" data-i="${i}"><span>${esc(x.from??'')}–${esc(x.to??'')} s</span><strong>${esc(x.visual||`Scéna ${i+1}`)}</strong></button>`).join(''):'<div class="item">Bez scén.</div>';e.querySelectorAll('.timeline-step').forEach(b=>b.onclick=()=>{reelPreviewIndex=Number(b.dataset.i)||0;showReelFrame();});}
function nextReelPreview(){const frames=window.__bcReelFrames||[];if(!frames.length)return toast('Nejdřív sestav náhled.','bad');reelPreviewIndex=(reelPreviewIndex+1)%frames.length;showReelFrame();}
function playReelPreview(){const frames=window.__bcReelFrames||[],btn=$('#reelPreviewPlay');if(!frames.length)return toast('Nejdřív sestav náhled.','bad');if(reelPreviewTimer){clearInterval(reelPreviewTimer);reelPreviewTimer=null;btn.textContent='Přehrát';return;}btn.textContent='Pauza';reelPreviewTimer=setInterval(()=>nextReelPreview(),2200);}
function exportReelStoryboard(){const p=pd().lastReelPlan;if(!p)return toast('Nejdřív vytvoř Reel plán.','bad');const photos=selectedMedia().map(x=>x.name),html=`<!doctype html><meta charset="utf-8"><title>${esc(p.title||'Reel storyboard')}</title><style>body{font-family:system-ui;max-width:900px;margin:40px auto;padding:0 20px;color:#111}article{border:1px solid #ddd;border-radius:14px;padding:16px;margin:10px 0}small{color:#666}</style><h1>${esc(p.title||'Reel storyboard')}</h1><p><strong>Hook:</strong> ${esc(p.hook||'')}</p><p><strong>Lokální soubory:</strong> ${esc(photos.join(', ')||'žádné')}</p>${(p.shotList||[]).map((x,i)=>`<article><small>${esc(x.from??'')}–${esc(x.to??'')} s</small><h2>${i+1}. ${esc(x.visual||'')}</h2><p><strong>Text:</strong> ${esc(x.onScreenText||'')}</p><p><strong>Voice:</strong> ${esc(x.voiceover||'')}</p></article>`).join('')}<h2>CTA</h2><p>${esc(p.cta||'')}</p>`;downloadText(`reel-storyboard-${dayKey()}.html`,html,'text/html;charset=utf-8');}
async function enableNotifications(){if(!('Notification'in window))return toast('Tento prohlížeč nepodporuje oznámení.','bad');const permission=await Notification.requestPermission();state.prefs.notifications=permission==='granted';persist(false);renderPwaState();if(permission==='granted'){toast('Upozornění při otevření aplikace jsou zapnutá.','ok');maybeDueNotification(true);}else toast('Oznámení nebyla povolena.','bad');}
async function requestPersistentStorage(){if(!navigator.storage?.persist)return toast('Trvalé úložiště tento prohlížeč nepodporuje.','bad');const ok=await navigator.storage.persist();renderPwaState();toast(ok?'Telefon přidělil aplikaci trvalé úložiště.':'Prohlížeč trvalé úložiště nepřidělil.','ok');}
async function renderPwaState(){const e=$('#pwaState');if(!e)return;let persisted=false;try{persisted=await navigator.storage?.persisted?.()||false;}catch{}e.textContent=`Oznámení: ${'Notification'in window?Notification.permission:'nepodporováno'} · trvalé úložiště: ${persisted?'ANO':'NE'} · verze 11.1 META SAFE`;e.className='status-line '+(persisted?'ok':'');}
async function checkAppUpdate(){if(!('serviceWorker'in navigator))return toast('Service worker není dostupný.','bad');const r=await navigator.serviceWorker.getRegistration();if(!r)return toast('Aplikace zatím není registrovaná jako PWA.','bad');await r.update();toast('Kontrola aktualizace dokončena. Pokud je nová verze, načte se při dalším otevření.','ok');renderPwaState();}
async function maybeDueNotification(force=false){if(!state.prefs?.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const today=dayKey();if(!force&&state.prefs.lastDueNotice===today)return;let due=0,over=0;for(const p of Object.values(state.projectsData||{}))for(const x of p.leads||[]){if(Number(x.stage)>=4)continue;if(x.followUp===today)due++;if(x.followUp&&x.followUp<today)over++;}if(!due&&!over)return;try{const reg=await navigator.serviceWorker?.ready;await reg?.showNotification('Business Control ONE',{body:`Follow-up: ${due} dnes · ${over} po termínu. Otevři Prodej a vyřiď priority.`,tag:'bc-due-'+today,renotify:false});state.prefs.lastDueNotice=today;persist(false);}catch{}}

