function renderProducts(){const p=$('#products');p.innerHTML=pd().products.length?pd().products.map(x=>{const price=Number(x.price)||0,cost=Number(x.cost)||0,margin=price?Math.round((price-cost)/price*100):0;return `<div class=item><strong>${esc(x.name)} · ${esc(x.status||'test')}</strong>${money(price)} · náklad ${money(cost)} · marže ${margin}%<div class=muted>${esc(x.url||'')}</div><div class=item-actions><button class="btn small productContent" data-id="${x.id}">AI obsah</button><button class="btn small productDelete" data-id="${x.id}">Smazat</button></div></div>`;}).join(''):'<div class=item>Zatím bez produktů.</div>';$$('.productContent').forEach(b=>b.onclick=()=>productToContent(b.dataset.id));$$('.productDelete').forEach(b=>b.onclick=()=>{const x=pd().products.find(y=>y.id===b.dataset.id);pd().products=pd().products.filter(y=>y.id!==b.dataset.id);recordActivity('shop',`Smazán produkt: ${x?.name||'neznámý'}`);renderProducts();});}
function addProduct(){const n=$('#prodName').value.trim();if(!n)return toast('Chybí název produktu.','bad');pd().products.unshift({id:crypto.randomUUID(),name:n,price:Number(String($('#prodPrice').value).replace(',','.'))||0,cost:Number(String($('#prodCost').value).replace(',','.'))||0,url:$('#prodUrl').value.trim(),status:$('#prodStatus').value,createdAt:new Date().toISOString()});['prodName','prodPrice','prodCost','prodUrl'].forEach(id=>$('#'+id).value='');recordActivity('shop',`Přidán produkt: ${n}`);renderProducts();}
function productToContent(id){const x=pd().products.find(y=>y.id===id);if(!x)return;$('#cmd').value=`Vytvoř pro produkt ${x.name} (${money(x.price)}) prodejní příspěvek, který odpovídá stylu projektu. URL: ${x.url||'neuvedena'}`;pd().draft.cmd=$('#cmd').value;persist();activateTab('today');}
