function loadSbSession(){try{return JSON.parse(localStorage.getItem(SB_SESSION)||'null');}catch{return null;}}
function saveSbSession(s){sbSession=s;s?localStorage.setItem(SB_SESSION,JSON.stringify(s)):localStorage.removeItem(SB_SESSION);}
async function sbFetch(path,opt={},retry=true){let s=sbSession,headers={apikey:SB_KEY,'content-type':'application/json',...(opt.headers||{})};if(s?.access_token)headers.Authorization=`Bearer ${s.access_token}`;let r=await fetch(SB_URL+path,{...opt,headers});if(r.status===401&&retry&&s?.refresh_token){s=await sbRefresh();if(s){headers.Authorization=`Bearer ${s.access_token}`;r=await fetch(SB_URL+path,{...opt,headers});}}const text=await r.text();let j;try{j=text?JSON.parse(text):null;}catch{j=text;}if(!r.ok)throw new Error(j?.msg||j?.message||j?.error_description||j?.error||`Cloud HTTP ${r.status}`);return j;}
async function sbRefresh(){if(!sbSession?.refresh_token)return null;try{const r=await fetch(`${SB_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:SB_KEY,'content-type':'application/json'},body:JSON.stringify({refresh_token:sbSession.refresh_token})}),j=await r.json();if(!r.ok)throw new Error();saveSbSession(j);return j;}catch{saveSbSession(null);return null;}}
async function cloudLogin(register=false){const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value;if(!email||password.length<8)return toast('Cloud účet vyžaduje e-mail a heslo minimálně 8 znaků.','bad');try{const path=register?'/auth/v1/signup':'/auth/v1/token?grant_type=password',j=await sbFetch(path,{method:'POST',body:JSON.stringify({email,password})},false);if(j?.access_token){saveSbSession(j);toast('Cloud účet přihlášen.','ok');await cloudIdentity();}else toast('Registrace vytvořena. Pokud je zapnuté potvrzení e-mailu, potvrď zprávu a pak se přihlas.','ok');renderCloudState();}catch(e){toast(e.message,'bad');}}
async function cloudIdentity(){if(!sbSession?.access_token){currentCloudUser=currentOrg=null;return null;}try{currentCloudUser=await sbFetch('/auth/v1/user');const m=await sbFetch('/rest/v1/memberships?select=organization_id,role,organizations(id,name,slug)&order=created_at.asc&limit=1');currentOrg=m?.[0]?.organizations||null;renderCloudState();return {user:currentCloudUser,org:currentOrg};}catch(e){currentCloudUser=currentOrg=null;renderCloudState();return null;}}
async function cloudCreateOrg(){if(!sbSession)return toast('Nejdřív se přihlas do Business Cloud.','bad');const name=$('#cloudOrgName').value.trim();if(!name)return toast('Zadej název firmy.','bad');try{await sbFetch('/rest/v1/rpc/create_my_organization',{method:'POST',body:JSON.stringify({org_name:name,org_slug:null})});await cloudIdentity();toast('Organizace založena.','ok');}catch(e){toast(e.message,'bad');}}
async function remoteSnapshot(){if(!currentCloudUser||!currentOrg)await cloudIdentity();if(!currentCloudUser||!currentOrg)return null;const arr=await sbFetch(`/rest/v1/app_snapshots?select=organization_id,user_id,app_key,data,updated_at&app_key=eq.${encodeURIComponent(APP_SNAPSHOT_KEY)}&limit=1`);return arr?.[0]||null;}
function cleanStateForCloud(){const clone=structuredClone(state);clone.cloud={...clone.cloud,dirty:false,conflict:false};return clone;}
async function cloudPull(){try{const r=await remoteSnapshot();if(!r){toast('V cloudu zatím není žádná záloha.','ok');return;}if(state.cloud.dirty&&state.cloud.lastCloudUpdatedAt&&r.updated_at!==state.cloud.lastCloudUpdatedAt&&!confirm('Lokální i cloudová data se změnila. Načtením cloudu zahodíš lokální změny. Pokračovat?'))return;saveRecoveryPoint('Před načtením cloudu');state=migrate(r.data);state.cloud.lastCloudUpdatedAt=r.updated_at;state.cloud.lastSyncAt=new Date().toISOString();state.cloud.dirty=false;state.cloud.conflict=false;persist(false);$('#project').value=state.project;loadDraft();renderAll();recordActivity('cloud','Načtena data z Business Cloudu');toast('Cloudová data načtena.','ok');renderCloudState();}catch(e){toast('Cloud pull: '+e.message,'bad');}}
async function cloudPush(force=false,silent=false){if(!sbSession)return;if(!currentCloudUser||!currentOrg)await cloudIdentity();if(!currentCloudUser||!currentOrg){if(!silent)toast('Cloud účet nemá organizaci.','bad');return;}try{const remote=await remoteSnapshot();if(!force&&remote&&state.cloud.dirty){const known=state.cloud.lastCloudUpdatedAt;if((!known||remote.updated_at!==known)){state.cloud.conflict=true;persist(false);renderCloudState();if(!silent)toast('Cloud konflikt: nejdřív načti cloud nebo použij Vynutit přepsání.','bad');return;}}const body={organization_id:currentOrg.id,user_id:currentCloudUser.id,app_key:APP_SNAPSHOT_KEY,data:cleanStateForCloud(),updated_at:new Date().toISOString()},rows=await sbFetch('/rest/v1/app_snapshots?on_conflict=organization_id,user_id,app_key',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=representation'},body:JSON.stringify(body)}),row=Array.isArray(rows)?rows[0]:rows;state.cloud.lastCloudUpdatedAt=row?.updated_at||body.updated_at;state.cloud.lastSyncAt=new Date().toISOString();state.cloud.dirty=false;state.cloud.conflict=false;persist(false);renderCloudState();if(!silent){recordActivity('cloud','Uložena data do Business Cloudu');toast('Uloženo do Business Cloud.','ok');}}catch(e){if(!silent)toast('Cloud push: '+e.message,'bad');}}
function scheduleCloudSync(){if(!sbSession)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudPush(false,true),6500);}
function renderCloudState(){const e=$('#cloudAccountState');if(!sbSession){e.className='status-line';e.textContent='Cloud účet: nepřihlášen. Lokální data zůstávají v tomto zařízení.';return;}const parts=[currentCloudUser?.email||'přihlášen',currentOrg?.name||'bez organizace',state.cloud.dirty?'lokální změny čekají':state.cloud.lastSyncAt?'synchronizováno':'připraven'];if(state.cloud.conflict)parts.push('KONFLIKT');e.textContent=parts.join(' · ');e.className='status-line '+(state.cloud.conflict?'bad':currentOrg?'ok':'');}
function exportBackup(){captureDraft();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`business-control-one-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function importBackup(file){try{const raw=JSON.parse(await file.text());if(!confirm('Import nahradí lokální stav Business Control ONE. Pokračovat?'))return;saveRecoveryPoint('Před importem JSON');state=migrate(raw);persist();$('#project').value=state.project;loadDraft();renderAll();toast('Záloha importována.','ok');}catch(e){toast('Import selhal: '+e.message,'bad');}}
function controlDate(){return dayKey();}
function controlRoomData(){
  const today=controlDate(), now=new Date(), all=[];
  let due=0, overdue=0, pipeline=0, cashOver=0, activeJobs=0, contentReady=0, contentGap=0;
  for(const [key,p] of Object.entries(state.projectsData||{})){
    const leads=p.leads||[]; const jobs=p.jobs||[];
    for(const l of leads){
      const value=Number(l.value)||0;
      if(Number(l.stage||0)<4) pipeline+=value;
      if(l.followUp){if(l.followUp===today)due++; if(l.followUp<today)overdue++;}
    }
    for(const j of jobs){if(j.status==='planned'||j.status==='in_progress')activeJobs++; if(j.paymentStatus!=='paid'&&j.paymentDue&&j.paymentDue<today)cashOver+=Number(j.revenue)||0;}
    if(p.lastCampaign||p.lastReelPlan||p.calendar?.some(x=>x?.date>=today)) contentReady++;
    const score=(leads.filter(l=>Number(l.stage||0)<4).length*3)+(jobs.filter(j=>j.status!=='done').length*2)+(p.lastReelPlan?0:1);
    if(score) all.push({key,name:projects[key]?.name||key,score,leads:leads.length,jobs:jobs.length,pipeline:leads.reduce((a,l)=>a+(Number(l.value)||0),0)});
  }
  contentGap=Math.max(0,7-contentReady);
  const actions=due+overdue+activeJobs+contentGap;
  const salesPressure=pipeline>0?Math.min(100,Math.round(((overdue*15000)+(activeJobs*20000)+(contentGap*5000))/Math.max(pipeline,1)*100)):100;
  return {today,due,overdue,pipeline,cashOver,activeJobs,contentReady,contentGap,actions,salesPressure,projects:all.sort((a,b)=>b.score-a.score)};
}
function renderControlRoom(){
  const d=controlRoomData();
  const set=(id,v)=>{const e=$('#'+id);if(e)e.textContent=v;};
  set('controlActions',d.actions);set('controlSalesPressure',d.salesPressure+' %');set('controlCashRisk',money(d.cashOver));set('controlContentGap',d.contentGap);
  const meta=document.querySelector('#metaProjectState');set('controlMeta',meta?.textContent?.replace('Meta: ','')||'Kontrola');
  const snap=state?.cloud?.conflict?'KONFLIKT':state?.cloud?.dirty?'ZMĚNY': 'OK';set('controlDataHealth',snap);
  const q=$('#controlQueue'); if(q){const rows=[];
    if(d.overdue)rows.push(['URGENT','Vyřídit '+d.overdue+' follow-upů po termínu.','Prodej']);
    if(d.due)rows.push(['DNES','Vyřídit '+d.due+' follow-upů naplánovaných na dnešek.','CRM']);
    if(d.cashOver)rows.push(['CASH','Prověřit pohledávky po splatnosti '+money(d.cashOver)+'.','Zakázky']);
    if(d.contentGap)rows.push(['OBSAH','Doplnit obsahový plán – aktuálně chybí cca '+d.contentGap+' dní.','Obsah / Reels']);
    if(!d.overdue&&!d.due&&!d.cashOver&&!d.contentGap)rows.push(['STABILNÍ','Největší otevřená priorita je obchodní pipeline a rozpracované zakázky.','Řídicí místnost']);
    q.innerHTML=rows.map(x=>`<div class="item control-action"><span class="format-badge">${esc(x[0])}</span><strong>${esc(x[1])}</strong><span class="muted">${esc(x[2])}</span></div>`).join('');
  }
  const h=$('#controlHygiene'); if(h){const rows=[];
    for(const [key,p] of Object.entries(state.projectsData||{})){const missing=[];const leads=p.leads||[];if(leads.some(l=>!l.followUp&&Number(l.stage||0)<4))missing.push('leady bez follow-up');if(leads.some(l=>!l.contact))missing.push('leady bez kontaktu');if((p.jobs||[]).some(j=>!j.paymentDue&&j.status!=='done'))missing.push('zakázky bez splatnosti');if(!p.lastReelPlan)missing.push('chybí aktuální Reel plán');if(missing.length)rows.push(`<div class="item"><strong>${esc(projects[key]?.name||key)}</strong><div class="muted">${esc(missing.join(' · '))}</div></div>`);}
    h.innerHTML=rows.join('')||'<div class="item">Žádné zásadní datové mezery.</div>';
  }
  const sys=$('#controlSystem');if(sys){sys.innerHTML=`<div class="item"><strong>Lokální stav</strong><div class="muted">${state.cloud?.dirty?'Lokální změny čekají na synchronizaci.':'Bez čekajících změn.'}</div></div><div class="item"><strong>Recovery</strong><div class="muted">${recoveryPoints().length} uložených bodů</div></div><div class="item"><strong>Fotky</strong><div class="muted">Optimalizované náhledy + omezená cache</div></div><div class="item"><strong>Meta</strong><div class="muted">Publikace vyžaduje platný token a ruční potvrzení.</div></div>`;}
  const pc=$('#controlProjects');if(pc){pc.innerHTML=d.projects.map(x=>`<div class="project-card"><strong>${esc(x.name)}</strong><span class="muted">${x.leads} leadů · ${x.jobs} zakázek</span><span class="muted">Pipeline ${money(x.pipeline)}</span><span class="pill subtle">Priorita ${x.score}</span></div>`).join('')||'<div class="item">Zatím bez projektových dat.</div>';}
}
